cpp.setup:
auto* control = new fluent::collections::Timeline(%PARENT%);
control->setHeaderText(QStringLiteral("Release milestones"));
auto* model = new QStandardItemModel(control);
for (const auto& label : {QStringLiteral("Spec signed off"), QStringLiteral("API frozen"), QStringLiteral("Beta release")})
    model->appendRow(new QStandardItem(label));
control->setModel(model);
control->setAnimationEnabled(false);
model->setData(model->index(0, 0), QStringLiteral("09:00"), fluent::collections::Timeline::TimestampRole);
model->setData(model->index(0, 0), QStringLiteral("Requirements reviewed"), fluent::collections::Timeline::DescriptionRole);
model->setData(model->index(0, 0), fluent::collections::Timeline::Success, fluent::collections::Timeline::StatusRole);
model->setData(model->index(1, 0), QStringLiteral("11:30"), fluent::collections::Timeline::TimestampRole);
model->setData(model->index(1, 0), QStringLiteral("Public API stable"), fluent::collections::Timeline::DescriptionRole);
model->setData(model->index(1, 0), fluent::collections::Timeline::Active, fluent::collections::Timeline::StatusRole);
model->setData(model->index(2, 0), QStringLiteral("15:00"), fluent::collections::Timeline::TimestampRole);
model->setData(model->index(2, 0), QStringLiteral("Ready for feedback"), fluent::collections::Timeline::DescriptionRole);
model->setData(model->index(2, 0), fluent::collections::Timeline::Neutral, fluent::collections::Timeline::StatusRole);
